// The bundled seed: generated by the worker from the local import at build time (scripts/seed-mobile.mjs),
// and primed into the read cache once on a device with no saved catalogue (Client.Seed).
import './helpers/browser.mjs';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ensure } from '../dist/client/Seed.js';
import { store } from '../dist/client/Storage.js';
import { load } from '../dist/client/Search.js';
import { cachedResponses } from '../dist/client/packages/hedge/src/Client/Offline.js';
import { toArray } from '../dist/client/fable_modules/fable-library-js.4.29.0/List.js';

const dir=mkdtempSync(join(tmpdir(),'native-plants-seed-'));
execFileSync(process.execPath,[new URL('../scripts/seed-mobile.mjs',import.meta.url).pathname,dir],{stdio:'pipe'});
const catalogue=readFileSync(join(dir,'catalogue.json'),'utf8'), accounts=readFileSync(join(dir,'accounts.json'),'utf8');

test('the build-time seed is the real catalogue and every account, agreeing on the revision',()=>{
  const c=JSON.parse(catalogue), a=JSON.parse(accounts);
  assert.ok(c.plants.length>400,'the full catalogue');
  assert.equal(a.plants.length,c.plants.length);
  assert.equal(a.revision,c.revision);
  assert.ok(a.plants.every(p=>Array.isArray(p.sections) && p.card && p.card.id));
  assert.ok(c.glossary.length>0 && c.references.length>0);
});

test('on a device with no saved catalogue the seed primes the cache once, and only on the bundled app',async()=>{
  const files={'seed/catalogue.json':catalogue,'seed/accounts.json':accounts};
  globalThis.fetch=async url=>files[url]?new Response(files[url]):new Response('',{status:404});
  assert.equal(await ensure(),false,'web build: nothing to do');
  globalThis.window.API_ORIGIN='https://api.test';
  assert.equal(await ensure(),true);
  const saved=toArray(await cachedResponses(store,'','/api/plants/catalogue'));
  assert.equal(saved.length,1);assert.equal(saved[0][1].Body,catalogue);
  const count=JSON.parse(catalogue).plants.length;
  assert.equal(toArray(await cachedResponses(store,'','/api/plants/plant/')).length,count,'every account is readable singly');
  assert.equal(toArray(await load()).length,count,'and searchable');
  assert.equal(await store.Get('warm/catalogue'),JSON.parse(catalogue).revision,'the warm-up is recorded as done for this revision');
  assert.equal(await ensure(),false,'a saved catalogue is left alone');
  delete globalThis.window.API_ORIGIN;
});
